error_invalid_url:
URL inválida: {url}
  ayuda: usa una URL http(s) válida, p. ej. https://example.com/gallery/123
  nota: esquemas válidos http/https y longitud ≤2048

error_backend_failed:
backend '{name}' falló con código de salida {code}
  stderr: {stderr}
  ayuda: revisa los logs de {name} con --verbose
  nota: RUST_LOG=debug para tracing detallado

error_config_parse:
error de parseo de config en {path}: {source}
  ayuda: revisa la sintaxis TOML
  nota: ver https://toml.io/en/v1.0.0
